import type pg from 'pg';

// Bulk synthetic data for query-plan evidence (HDX-32 / P01). Everything is generated by SQL inside a disposable database:
// no target, no model, no network. Rows are shaped like the ones the product writes (same columns, same JSONB paths) but
// carry no real content. Deterministic: the same options always produce the same row counts, distributions and ids.

export type SeedScale = { targets: number; cases: number; runs: number; adaptiveShare: number; versions: number };
export const defaultScale: SeedScale = { targets: 8, cases: 40, runs: 30000, adaptiveShare: 0.15, versions: 6 };

const categories = ['prompt_injection', 'cross_patient', 'unintended_tool_action'];
const severities = ['low', 'medium', 'high', 'critical'];

/**
 * Deterministic, RFC 4122-shaped uuid for (namespace, n): the md5 digest with the version (4) and variant (8) nibbles set, so the
 * product's z.uuid() validation accepts it. 122 bits survive, which is collision-free at these scales.
 */
const uid = (ns: string, n: string) => `(substr(md5('${ns}:' || ${n}), 1, 12) || '4' || substr(md5('${ns}:' || ${n}), 14, 3) || '8' || substr(md5('${ns}:' || ${n}), 18, 15))::uuid`;

export async function seedScale(pool: pg.Pool, partial: Partial<SeedScale> = {}) {
  const s = { ...defaultScale, ...partial };
  // Statistics and visibility maps are refreshed explicitly below. Autovacuum is switched off for the seeded tables so a background
  // worker cannot perturb plan timings, and cannot still be attached to the database when the harness drops it.
  for (const table of ['runs', 'events', 'candidates', 'adaptive_cases', 'regressions', 'regression_identities']) await pool.query(`ALTER TABLE ${table} SET (autovacuum_enabled = false)`);
  const selectedRuns = Math.round(s.runs * (1 - s.adaptiveShare));
  const adaptiveRuns = s.runs - selectedRuns;
  await pool.query(`INSERT INTO credentials(id,ciphertext) SELECT ${uid('cred', 'i::text')}, 'perf-fixture-not-a-secret' FROM generate_series(1, $1::int * 2) i`, [s.targets]);
  await pool.query(`INSERT INTO targets(id,name,base_url,user_a_credential,user_b_credential)
    SELECT ${uid('target', 'i::text')}, 'Perf target ' || i, 'http://127.0.0.1:9/', ${uid('cred', '(i*2-1)::text')}, ${uid('cred', '(i*2)::text')} FROM generate_series(1, $1::int) i`, [s.targets]);
  // Published cases: category and severity live in the definition JSONB exactly as the case workspace authors them.
  await pool.query(`INSERT INTO cases(id,definition,family_id,state,authoring_mode)
    SELECT ${uid('case', 'i::text')}, jsonb_build_object('title','Perf case ' || i,'category',(ARRAY['${categories.join("','")}'])[1 + i % 3],'user','A',
      'expectedSafeBehavior','Do not obey untrusted override','actions',jsonb_build_array(jsonb_build_object('kind','chat_turn','message','perf probe ' || i)),
      'rubric',jsonb_build_object('v',1,'subcategory','perf boundary ' || (i % 5),'severity',(ARRAY['${severities.join("','")}'])[1 + i % 4])),
      ${uid('case', 'i::text')}, 'published', 'versioned' FROM generate_series(1, $1::int) i`, [s.cases]);
  // Selected runs: ~5% have no observed version (a legacy or unverified handshake), the rest spread over `versions` labels.
  await pool.query(`INSERT INTO runs(id,target_id,case_id,definition,target_snapshot,status,outcome,version,created_at,started_at,finished_at,adaptive)
    SELECT ${uid('run', 'i::text')}, ${uid('target', '(1 + i % $2::int)::text')}, ${uid('case', '(1 + i % $3::int)::text')},
      jsonb_build_object('case', c.definition), jsonb_build_object('name','Perf target ' || (1 + i % $2::int)), 'finished',
      (ARRAY['safe','safe','safe','inconclusive','pending_review','blocked'])[1 + i % 6],
      CASE WHEN i % 20 = 0 THEN NULL ELSE 'perf-v' || (i * $4::int / GREATEST($1::int,1)) END,
      now() - (($1::int - i) * interval '10 seconds'), now() - (($1::int - i) * interval '10 seconds') + interval '1 second', now() - (($1::int - i) * interval '10 seconds') + interval '2 seconds', NULL
    FROM generate_series(1, $1::int) i JOIN cases c ON c.id = ${uid('case', '(1 + i % $3::int)::text')}`, [selectedRuns, s.targets, s.cases, s.versions]);
  await pool.query(`INSERT INTO runs(id,target_id,case_id,definition,target_snapshot,status,outcome,version,created_at,started_at,finished_at,adaptive)
    SELECT ${uid('arun', 'i::text')}, ${uid('target', '(1 + i % $2::int)::text')}, NULL, '{}'::jsonb, jsonb_build_object('name','Perf target ' || (1 + i % $2::int)), 'finished', 'safe',
      'perf-v' || (i * $3::int / GREATEST($1::int,1)), now() - (($1::int - i) * interval '30 seconds'), now() - (($1::int - i) * interval '30 seconds'), now() - (($1::int - i) * interval '30 seconds') + interval '5 seconds',
      jsonb_build_object('maxCases',3,'categories',to_jsonb(ARRAY['${categories.join("','")}']))
    FROM generate_series(1, $1::int) i`, [adaptiveRuns, s.targets, s.versions]);
  // Three execution cases per adaptive run; the category is a real column here, the definition is the admitted case.
  await pool.query(`INSERT INTO adaptive_cases(id,run_id,ordinal,category,source_case_id,definition,state,executed,created_at,finished_at)
    SELECT ${uid('ac', "(r.n * 3 + o)::text")}, r.id, o, (ARRAY['${categories.join("','")}'])[1 + (r.n + o) % 3], ${uid('case', '(1 + (r.n + o) % $2::int)::text')}, c.definition,
      (ARRAY['safe','safe','inconclusive','pending_review','blocked','incomplete'])[1 + (r.n + o) % 6], (r.n + o) % 7 <> 0, now(), now()
    FROM (SELECT i AS n, ${uid('arun', 'i::text')} AS id FROM generate_series(1, $1::int) i) r CROSS JOIN generate_series(1,3) o
    JOIN cases c ON c.id = ${uid('case', '(1 + (r.n + o) % $2::int)::text')}`, [adaptiveRuns, s.cases]);
  // Candidates for every pending_review selected run (a third confirmed, a third rejected) and for pending_review adaptive cases.
  await pool.query(`INSERT INTO candidates(id,run_id,state,created_at,adaptive_case_id)
    SELECT ${uid('cand', 'r.id::text')}, r.id, (ARRAY['pending_review','confirmed','rejected'])[1 + (row_number() OVER (ORDER BY r.created_at))::int % 3], r.created_at, NULL
    FROM runs r WHERE r.adaptive IS NULL AND r.outcome = 'pending_review'`);
  await pool.query(`INSERT INTO candidates(id,run_id,state,created_at,adaptive_case_id)
    SELECT ${uid('cand', 'ac.id::text')}, ac.run_id, (ARRAY['pending_review','confirmed','rejected'])[1 + (row_number() OVER (ORDER BY ac.id))::int % 3], ac.created_at, ac.id
    FROM adaptive_cases ac WHERE ac.state = 'pending_review'`);
  // Regression identities: one per ~50 runs, each first seen on a selected-run candidate; confirmed findings link to an identity.
  const identities = Math.max(1, Math.round(s.runs / 50));
  await pool.query(`INSERT INTO regression_identities(id,normalization_version,fingerprint,category,user_slot,canonical,first_seen_candidate_id)
    SELECT ${uid('ident', 'k.n::text')}, 1, md5('fp-a:' || k.n) || md5('fp-b:' || k.n), CASE WHEN k.n % 25 = 0 THEN NULL ELSE (ARRAY['${categories.join("','")}'])[1 + k.n % 3] END, 'A',
      jsonb_build_object('v',1,'user','A','actions',jsonb_build_array(jsonb_build_object('kind','chat_turn','message','perf identity ' || k.n))), k.id
    FROM (SELECT id, (row_number() OVER (ORDER BY created_at))::int AS n FROM candidates WHERE adaptive_case_id IS NULL) k WHERE k.n <= $1::int`, [identities]);
  await pool.query(`INSERT INTO regressions(id,candidate_id,source_run_id,definition,identity_id,created_at)
    SELECT ${uid('reg', 'c.id::text')}, c.id, c.run_id, r.definition->'case', ${uid('ident', "(1 + (row_number() OVER (ORDER BY c.created_at))::int % $1::int)::text")}, c.created_at
    FROM candidates c JOIN runs r ON r.id = c.run_id WHERE c.state = 'confirmed' AND c.adaptive_case_id IS NULL`, [identities]);
  // Five events per selected run, shaped like the worker's (agent, kind, detail); the turn event carries ~1.2 KB of synthetic text.
  // Real per-case event bytes are measured by the 100-case baseline (baseline.ts); this only gives coverage's EXISTS probe a realistic table.
  await pool.query(`INSERT INTO events(run_id,event,created_at)
    SELECT r.id, jsonb_build_object('agent', e.agent, 'kind', e.kind, 'detail', CASE WHEN e.kind = 'turn' THEN jsonb_build_object('turn', 1, 'reply', repeat('synthetic assistant text ', 48)) ELSE '{}'::jsonb END), r.created_at + e.n * interval '100 milliseconds'
    FROM runs r CROSS JOIN (VALUES (1,'system','started'),(2,'target','session'),(3,'target','turn'),(4,'judge','verdict'),(5,'system','finished')) AS e(n, agent, kind)
    WHERE r.adaptive IS NULL`);
  // Analyze so the planner sees real statistics, and vacuum so index-only scans have a visibility map to use.
  for (const table of ['credentials', 'targets', 'cases', 'runs', 'adaptive_cases', 'candidates', 'regression_identities', 'regressions', 'events']) await pool.query(`VACUUM (ANALYZE) ${table}`);
  const counts = (await pool.query(`SELECT (SELECT count(*)::int FROM runs) AS runs, (SELECT count(*)::int FROM runs WHERE adaptive IS NOT NULL) AS "adaptiveRuns", (SELECT count(*)::int FROM adaptive_cases) AS "adaptiveCases",
    (SELECT count(*)::int FROM candidates) AS candidates, (SELECT count(*)::int FROM regression_identities) AS identities, (SELECT count(*)::int FROM regressions) AS regressions,
    (SELECT count(*)::int FROM cases) AS cases, (SELECT count(*)::int FROM events) AS events, (SELECT count(*)::int FROM targets) AS targets`)).rows[0] as Record<string, number>;
  return { scale: s, counts };
}
